import{c as a,Q as n,j as t,m as s}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse('{"title":"Loop Engineering: Build an AI That Codes While You Sleep","description":"","frontmatter":{"url":"https://x.com/phosphenq/status/2068468824421364103","title":"Loop Engineering: Build an AI That Codes While You Sleep","author":"phosphenq","archived":"2026-06-21T00:00:00.000Z","handle":"@phosphenq","published":"2026-06-20T00:00:00.000Z","stats":"842 likes · 113 retweets · 1971 bookmarks · 608813 views","tags":["loop-engineering","claude-code","codex","automation","subagents","worktree"],"type":"twitter-article"},"headers":[],"relativePath":"research/tweets/2026-06-20-@phosphenq-364103.md","filePath":"research/tweets/2026-06-20-@phosphenq-364103.md","lastUpdated":1785909234000}'),o={name:"research/tweets/2026-06-20-@phosphenq-364103.md"};function i(r,e,l,p,h,d){return n(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="loop-engineering-build-an-ai-that-codes-while-you-sleep-—-phosphenq" tabindex="-1">Loop Engineering: Build an AI That Codes While You Sleep — @phosphenq <a class="header-anchor" href="#loop-engineering-build-an-ai-that-codes-while-you-sleep-—-phosphenq" aria-label="Permalink to &quot;Loop Engineering: Build an AI That Codes While You Sleep — @phosphenq&quot;">​</a></h1><p><strong>來源</strong>：<a href="https://x.com/phosphenq/status/2068468824421364103" target="_blank" rel="noreferrer">https://x.com/phosphenq/status/2068468824421364103</a><strong>作者</strong>：phosphenq（@phosphenq） <strong>發布日期</strong>：2026-06-20 <strong>收錄日期</strong>：2026-06-21 <strong>類型</strong>：Twitter Article <strong>統計</strong>：842 likes · 113 retweets · 1971 bookmarks · 608813 views</p><hr><h2 id="全文" tabindex="-1">全文 <a class="header-anchor" href="#全文" aria-label="Permalink to &quot;全文&quot;">​</a></h2><p>Last December, Boris Cherny shipped 259 pull requests in a single month. Every one written by Claude. He says he did not open an editor the whole time. His job was not to write code. It was to write the thing that writes the code. Peter Steinberger put it in two lines that have been seen over 8 million times: &quot;You shouldn&#39;t be prompting coding agents anymore. You should be designing loops that prompt your agents.&quot; That is loop engineering. You build a small system that finds the work, hands it to an agent, checks the result, and decides the next move, then you let it run while you sleep. The catch arrived the same month. Someone else&#39;s loop ran for eleven days unwatched and burned $47,000 before anyone noticed. So this is really two skills, and almost everyone teaches only the first: building a loop that ships work, and building the brakes that keep it from running you off a cliff. One question decides which loop you built: does it converge on something true, or is it just an expensive random walk?</p><h2 id="_1-a-loop-is-six-pieces-and-one-question" tabindex="-1">1. A loop is six pieces and one question <a class="header-anchor" href="#_1-a-loop-is-six-pieces-and-one-question" aria-label="Permalink to &quot;1. A loop is six pieces and one question&quot;">​</a></h2><p>Underneath the noise, a working loop is six parts. The list looks too plain the first time you see it. The detail inside each part is where a loop either holds together or leaks money overnight. You no longer build any of this by hand. A year ago a loop meant a pile of shell scripts you owned and babysat forever. Now the pieces ship inside the products, and the same six map onto both the OpenAI Codex app and Claude Code. Once you see that, the tool stops being the argument and the loop becomes the design.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PIECE          JOB IN THE LOOP           CODEX                      CLAUDE CODE</span></span>
<span class="line"><span>-------------  ------------------------  -------------------------  --------------------------</span></span>
<span class="line"><span>State          remember across runs      markdown / Linear (MCP)    markdown / Routines + MCP</span></span>
<span class="line"><span>Automations    run on a schedule         Automations tab + Triage   /loop (skill), Routines, /goal</span></span>
<span class="line"><span>Worktrees      isolate parallel agents   Worktree per thread        --worktree, isolation: worktree</span></span>
<span class="line"><span>Skills         codify your intent        ~/.agents/skills/SKILL.md   ~/.claude/skills/SKILL.md</span></span>
<span class="line"><span>Connectors     touch your real tools     MCP servers (config.toml)  MCP servers (.mcp.json)</span></span>
<span class="line"><span>Sub-agents     split maker from checker  TOML in .codex/agents/     .claude/agents/ + agent teams</span></span></code></pre></div><h2 id="_2-state-is-the-only-thing-the-next-run-inherits" tabindex="-1">2. State is the only thing the next run inherits <a class="header-anchor" href="#_2-state-is-the-only-thing-the-next-run-inherits" aria-label="Permalink to &quot;2. State is the only thing the next run inherits&quot;">​</a></h2><p>Start at the bottom, because everything else leans on it. A model forgets when a run ends. The conversation dies, the context clears, the next run wakes up knowing nothing. Memory in the chat dies with the run. It has to live on disk. In practice that is one file. A STATUS.md in the repo, or a Linear board reached through a connector, holding what is done, what is in progress, what is next, and the handful of things the loop must never touch.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># STATUS.md  (the loop reads this first, writes it last)</span></span>
<span class="line"><span>## Done</span></span>
<span class="line"><span>- [x] auth: migrated to tokens v2, tests green</span></span>
<span class="line"><span>## In progress</span></span>
<span class="line"><span>- [ ] billing: webhook refactor (PR #214, CI red)</span></span>
<span class="line"><span>## Next</span></span>
<span class="line"><span>- [ ] dashboard: flaky test in test/charts</span></span>
<span class="line"><span>## Never</span></span>
<span class="line"><span>- do not modify infra/ without a human</span></span></code></pre></div><p>Treat the loop like a night shift you never watch. You are not judged by what it did at 3am. You are judged by the note waiting on your desk at nine. Design that note first and most of the loop designs itself.</p><h2 id="_3-automations-are-the-difference-between-a-loop-and-a-thing-you-ran-once" tabindex="-1">3. Automations are the difference between a loop and a thing you ran once <a class="header-anchor" href="#_3-automations-are-the-difference-between-a-loop-and-a-thing-you-ran-once" aria-label="Permalink to &quot;3. Automations are the difference between a loop and a thing you ran once&quot;">​</a></h2><p>A loop earns the name only when it fires on its own. In the Codex app you build one in the Automations tab: the repo, the prompt, the cadence. Runs that find something land in a Triage inbox; runs that find nothing archive themselves. OpenAI uses this for the unglamorous backbone of a codebase: daily issue triage, CI-failure summaries, catching the bug someone slipped in last week. Claude Code gets there through a few primitives, and the popular write-ups get the details wrong, so it is worth being exact. /loop is a skill, not a built-in command, and it re-runs a prompt on a cadence while your session is open. Recurring cloud jobs are Routines, set with /schedule, with a one-hour minimum, and they keep running with your laptop closed. There is no local crontab. The one worth learning is /goal. It runs until a condition you wrote is true, and after each turn a separate, smaller model checks whether you are actually done. The agent that wrote the code does not get to grade it.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Claude Code: run until it is genuinely finished, not until it feels finished</span></span>
<span class="line"><span>/goal all tests in test/auth pass and the lint step is clean</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Claude Code: a recurring cloud job (1-hour minimum)</span></span>
<span class="line"><span>/schedule daily PR triage at 9am</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Codex: an automation prompt (set the cadence in the form)</span></span>
<span class="line"><span>&quot;Weekdays 9am: scan open PRs, flag failing CI or no reviewer, post to Triage.&quot;</span></span></code></pre></div><p>Write the stop condition like a contract. &quot;All tests in test/auth pass&quot; is a contract. &quot;Make it better&quot; is how a loop runs until payday.</p><h2 id="_4-worktrees-keep-parallel-agents-out-of-each-other-s-way" tabindex="-1">4. Worktrees keep parallel agents out of each other&#39;s way <a class="header-anchor" href="#_4-worktrees-keep-parallel-agents-out-of-each-other-s-way" aria-label="Permalink to &quot;4. Worktrees keep parallel agents out of each other&#39;s way&quot;">​</a></h2><p>The moment you run more than one agent, the failure mode changes. It is no longer the model. It is two agents writing the same file, the same mess as two engineers committing to the same lines with nobody talking. A git worktree is the wall between them: a separate working directory on its own branch, sharing the repo history, so one agent&#39;s edits cannot reach another&#39;s checkout.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Claude Code: an isolated checkout per agent</span></span>
<span class="line"><span>claude --worktree feature-auth</span></span>
<span class="line"><span></span></span>
<span class="line"><span># or on a sub-agent, in .claude/agents/&lt;name&gt;.md frontmatter:</span></span>
<span class="line"><span>#   isolation: worktree</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Codex: choose &quot;Worktree&quot; when you open a thread (one detached HEAD each)</span></span></code></pre></div><p>One caveat the tool will not mention. Worktrees remove the collision, not the bottleneck. You are still the ceiling. However many agents you start, your own review bandwidth decides how many you can trust.</p><h2 id="_5-skills-are-your-intent-written-once-on-the-outside" tabindex="-1">5. Skills are your intent, written once, on the outside <a class="header-anchor" href="#_5-skills-are-your-intent-written-once-on-the-outside" aria-label="Permalink to &quot;5. Skills are your intent, written once, on the outside&quot;">​</a></h2><p>An agent starts every run cold and fills any gap in your intent with a confident guess. A skill is that intent written down where the model reads it each time, so it stops guessing. The format is the same on both tools: a folder with a SKILL.md holding instructions and a description, plus any scripts it needs. It fires when you call it by name or when your task matches its description, which is exactly why a flat, literal description beats a clever one.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># .claude/skills/triage/SKILL.md   (Codex: ~/.agents/skills/triage/SKILL.md)</span></span>
<span class="line"><span>---</span></span>
<span class="line"><span>name: triage</span></span>
<span class="line"><span>description: Read yesterday&#39;s CI failures, open issues, and recent</span></span>
<span class="line"><span>  commits; write each finding to STATUS.md as a task.</span></span>
<span class="line"><span>---</span></span>
<span class="line"><span>1. Pull failing CI and cluster by root cause.</span></span>
<span class="line"><span>2. Match each to the open issue or commit that caused it.</span></span>
<span class="line"><span>3. Write one STATUS.md task per real finding. Skip the noise.</span></span></code></pre></div><p>Without skills, every cycle relearns your project from scratch. With them, the loop gets a little sharper each morning.</p><h2 id="_6-connectors-let-the-loop-act-not-just-talk" tabindex="-1">6. Connectors let the loop act, not just talk <a class="header-anchor" href="#_6-connectors-let-the-loop-act-not-just-talk" aria-label="Permalink to &quot;6. Connectors let the loop act, not just talk&quot;">​</a></h2><p>A loop that can only see the filesystem is a toy. Connectors, built on the shared MCP standard, let the agent read your issue tracker, hit a staging API, query a database, post to a channel.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Claude Code</span></span>
<span class="line"><span>claude mcp add --transport http linear https://mcp.linear.app/mcp</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Codex</span></span>
<span class="line"><span>codex mcp add linear --url https://mcp.linear.app/mcp</span></span></code></pre></div><p>This is the line between an agent that says &quot;here is the fix&quot; and a loop that opens the pull request, links the ticket, and reports green on its own. Because both tools speak MCP, a connector you wire for one usually drops into the other.</p><h2 id="_7-sub-agents-keep-the-maker-away-from-the-checker" tabindex="-1">7. Sub-agents keep the maker away from the checker <a class="header-anchor" href="#_7-sub-agents-keep-the-maker-away-from-the-checker" aria-label="Permalink to &quot;7. Sub-agents keep the maker away from the checker&quot;">​</a></h2><p>The highest-value move in any loop is splitting the agent that writes from the agent that checks. A model reviewing its own work passes itself every time. A second agent, with different instructions and ideally a different model, catches what the first one talked itself into.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Codex: .codex/agents/reviewer.toml</span></span>
<span class="line"><span>name = &quot;reviewer&quot;</span></span>
<span class="line"><span>description = &quot;Adversarial PR reviewer: correctness, security, missing tests.&quot;</span></span>
<span class="line"><span>developer_instructions = &quot;Review like an owner. Assume the author is wrong</span></span>
<span class="line"><span>  until the diff proves otherwise.&quot;</span></span>
<span class="line"><span>model_reasoning_effort = &quot;high&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Claude Code: .claude/agents/reviewer.md frontmatter</span></span>
<span class="line"><span>#   name: reviewer</span></span>
<span class="line"><span>#   description: Adversarial reviewer. Use after any code change.</span></span>
<span class="line"><span>#   model: opus</span></span></code></pre></div><p>One explores, one implements, one verifies against the spec. This is what /goal already does underneath: a fresh model rules on whether the work is done. Second opinions cost tokens, because each agent runs its own model and tools, so spend them where being wrong is expensive.</p><h2 id="_8-what-one-loop-looks-like" tabindex="-1">8. What one loop looks like <a class="header-anchor" href="#_8-what-one-loop-looks-like" aria-label="Permalink to &quot;8. What one loop looks like&quot;">​</a></h2><p>Put the six together and a single thread becomes a small machine. A scheduled automation runs each morning on the repo. It calls your triage skill, which reads the overnight CI failures, the open issues, and the recent commits, and writes each real finding into STATUS.md. For every finding worth doing, the loop opens an isolated worktree, sends one sub-agent to draft the fix and a second to review it against your skills and your tests. Connectors open the PR and update the ticket. Whatever it cannot handle waits in your triage inbox. STATUS.md remembers what passed and what is still open, so tomorrow starts where today stopped. What you actually wake up to is a short handoff, not a wall of logs:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 9:00am — the loop&#39;s overnight handoff (your Triage inbox)</span></span>
<span class="line"><span>READY TO MERGE</span></span>
<span class="line"><span>  PR #218  fix flaky test in test/charts          CI green</span></span>
<span class="line"><span>  PR #219  retry webhook on 429, add backoff test  CI green</span></span>
<span class="line"><span>NEEDS YOU</span></span>
<span class="line"><span>  auth/session.ts  two safe ways to fix this; I picked neither, your call</span></span>
<span class="line"><span>QUIET</span></span>
<span class="line"><span>  7 scheduled runs found nothing and archived themselves</span></span></code></pre></div><p>You designed it once. You prompted none of it.</p><h2 id="_9-build-the-brakes-before-you-walk-away" tabindex="-1">9. Build the brakes before you walk away <a class="header-anchor" href="#_9-build-the-brakes-before-you-walk-away" aria-label="Permalink to &quot;9. Build the brakes before you walk away&quot;">​</a></h2><p>This is the half nobody teaches, and it decides whether your loop is an asset or a liability. That $47,000 bill was not a clever model gone rogue. It was two agents, an analyzer and a verifier, each politely asking the other for more work, with no step limit, no budget ceiling, and no stop condition. It ran eleven days. One cap would have killed it on the first. Install the brakes before the horsepower. Do not ship the engine until you have shipped the brake pedal.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Bolt these on BEFORE you walk away:</span></span>
<span class="line"><span>- step cap:        --max-turns 50            (hard stop, no exceptions)</span></span>
<span class="line"><span>- budget ceiling:  claude -p --max-budget-usd 10   (print mode; per phase)</span></span>
<span class="line"><span>- blast radius:    one worktree, one branch, read-only outside src/</span></span>
<span class="line"><span>- circuit breaker: same tool + same args 3x in a row = halt</span></span>
<span class="line"><span>- dead-man check:  write a heartbeat to STATUS.md each run; silence pages you</span></span></code></pre></div><p>Scope a loop by what it can destroy, not by what you want it to do: which repos, which branches, how many dollars, how many steps before it force-quits. Choose the blast radius first, the task second. And price it honestly. Steinberger&#39;s hundred-agent fleet is real, and it runs about $1.3 million a month. It works because OpenAI now employs him and pays the bill. The frontier case is sponsored. Yours is not. On a $20 to $200 plan, the loop that pays off is small, capped, and pointed at one dull job, not a swarm.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>THE COST SPREAD (all real, all from the last six months)</span></span>
<span class="line"><span>-----------------------------------------------------------------</span></span>
<span class="line"><span>259 PRs in 30 days    one engineer, 100% written by Claude</span></span>
<span class="line"><span>$47,000 in 11 days    a runaway loop with no cap, nobody watching</span></span>
<span class="line"><span>~$1.3M per month       a 100-agent fleet (the bill is sponsored)</span></span>
<span class="line"><span>-----------------------------------------------------------------</span></span>
<span class="line"><span>Same technology. The difference is the brakes.</span></span></code></pre></div><h2 id="_10-how-loops-die" tabindex="-1">10. How loops die <a class="header-anchor" href="#_10-how-loops-die" aria-label="Permalink to &quot;10. How loops die&quot;">​</a></h2><p>Every loop that fails dies one of four deaths. Learn the names now so you spot them at 3am. Runaway recursion. Two agents feed each other forever. The cure is the step cap and the budget ceiling above, nothing cleverer. Silent death. One developer&#39;s overnight run hit a full context window, stopped, then kept trying to resume into the same wall while still looking alive. Your loop can be dead for hours and still report progress. The cure is a heartbeat and a fresh context per phase, not one endless run. The random walk. With no verifiable stop condition, the loop drifts away from the goal instead of toward it. A passing test suite is a fixpoint it can reach. &quot;Looks done&quot; is not one. Comprehension debt. The faster a loop ships code you did not write, the wider the gap between what your repo does and what you understand. Let it run long enough unread and you stop being the engineer and become a rubber stamp. The cure is a human-read gate the loop is never allowed to skip.</p><h2 id="_11-build-the-loop-stay-the-engineer" tabindex="-1">11. Build the loop. Stay the engineer. <a class="header-anchor" href="#_11-build-the-loop-stay-the-engineer" aria-label="Permalink to &quot;11. Build the loop. Stay the engineer.&quot;">​</a></h2><p>Two people can build the identical loop and get opposite results. One uses it to move faster on work they understand to the bone. The other uses it to stop understanding the work at all. The loop cannot tell them apart. You can. Cherny&#39;s point was never that the work got easier. It is that the leverage moved: from the prompt to the loop, and from typing to judgment. That is a harder job than prompting, not a softer one. So here is the move, and it is small on purpose, because this is early and the costs swing wildly. Tomorrow morning, take the most boring job you still do by hand, triaging CI, closing stale issues, chasing a flaky test, and wrap one capped loop around it. Brakes first. Small enough that you still read every diff it ships. Nobody shipping 200 pull requests a month started with a hundred agents. They started with one loop they trusted, and they stayed the engineer the whole way. Build that one.</p><hr><h2 id="研究摘要" tabindex="-1">研究摘要 <a class="header-anchor" href="#研究摘要" aria-label="Permalink to &quot;研究摘要&quot;">​</a></h2><p><strong>TL;DR</strong>：Loop Engineering 六構件實踐指南——STATUS.md 狀態機 + Automations + Worktrees + Skills + Connectors + Maker/Checker 分離，讓 AI 自主寫程式而你只設計 Loop。</p><h3 id="核心論點" tabindex="-1">核心論點 <a class="header-anchor" href="#核心論點" aria-label="Permalink to &quot;核心論點&quot;">​</a></h3><ul><li>Loop 的六構件：① State（STATUS.md Done/In Progress/Next/Never）是唯一跨 run 繼承的東西 ② Automations（定時觸發）讓 loop 真正自主 ③ Worktrees 隔離平行 agent 避免 checkout 衝突 ④ Skills 是意圖外部化，一次定義跨 agent 複用 ⑤ Connectors 讓 loop 可行動而非只會說話 ⑥ Sub-agents 做 maker/checker 分離</li><li>Automations 是 loop 與「只跑一次的東西」的本質差別——Claude Code 用 <code>/loop</code> 或 cloud job（1h 最短），Codex 在表單設定週期</li><li>Maker/Checker 必須分離：同一 agent 不能既做又審，adversarial reviewer sub-agent（<code>.claude/agents/reviewer.md</code>）是標配</li><li>「走開前先裝煞車」：hard cap on PRs/tokens、human gate on merge/deploy，never Never 列表防止 loop 做超出範圍的事</li><li>Loop 死亡十大模式包含：STATUS.md 沒更新、worktree 碰撞、Checker 與 Maker 是同一 agent、沒有 hard cap</li></ul><h3 id="關鍵數據-工具" tabindex="-1">關鍵數據 / 工具 <a class="header-anchor" href="#關鍵數據-工具" aria-label="Permalink to &quot;關鍵數據 / 工具&quot;">​</a></h3><ul><li>Boris Cherny：259 PRs in December with Claude，全程不開 editor</li><li>Peter Steinberger 推文 8M views：「你不應該再 prompt 了，你應該設計讓 AI 自主 prompt 的 Loop」</li><li>STATUS.md 格式：Done / In Progress / Next / Never 四區塊</li><li>Claude Code: <code>isolation: worktree</code> frontmatter in <code>.claude/agents/&lt;name&gt;.md</code></li><li>Codex: <code>.codex/agents/reviewer.toml</code> + Worktree 選項</li><li>觸發：Claude Code <code>/loop 1h</code>（最短），Codex 表單設定 cadence</li></ul><h3 id="批判性觀察" tabindex="-1">批判性觀察 <a class="header-anchor" href="#批判性觀察" aria-label="Permalink to &quot;批判性觀察&quot;">​</a></h3><ul><li>每構件均有具體 Claude Code/Codex 雙平台配置路徑，可行動性為同類文章最高</li><li>「How loops die」章節列 10 個失敗模式，防禦思維優先</li><li>缺乏 token 消耗/成本估算量化數字，實際 ROI 計算需自行補充</li></ul><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>A. Workspace 可行動性 (30%)</td><td>9/10</td><td>六構件逐一對應 Claude Code 配置，可直接套用到 workspace</td></tr><tr><td>B. 創新性 (20%)</td><td>7/10</td><td>Boris/Peter 故事已廣傳，但六構件結構化整合+雙平台對應有價值</td></tr><tr><td>C. 證據品質 (20%)</td><td>7/10</td><td>引用具體人物數字，配置範例片段可驗證</td></tr><tr><td>D. 技術深度 (15%)</td><td>8/10</td><td>STATUS.md 設計、worktree isolation、maker/checker 分離實作細節</td></tr><tr><td>E. 泛化性 (15%)</td><td>8/10</td><td>適用所有使用 Claude Code / Codex 的開發者</td></tr><tr><td><strong>加權總分</strong></td><td><strong>7.9/10</strong></td><td>A×0.3+B×0.2+C×0.2+D×0.15+E×0.15</td></tr></tbody></table><p><strong>整合決策</strong>：Agent <strong>理由</strong>：核心是建構多步驟自主 loop 流程（Automations + Sub-agents + Worktrees），屬 Agent 架構設計範疇</p>`,58)])])}const g=a(o,[["render",i]]);export{u as __pageData,g as default};
